"""Google Tasks that leak into the calendar as events.

A task with a due date *and time* is returned by Calendar API `events.list`
as an ordinary event: `event_type: "focusTime"`, no attendees, and a
`https://tasks.google.com/task/<id>` link in the description. Date-only
tasks never reach the calendar at all.

Detection only. Clearing the due date from here is not possible: the Tasks
API truncates `due` to a date, so it cannot distinguish a timed task from a
date-only one, and a write would strip due dates from tasks that were never
on the calendar. See CLAUDE.md.
"""

from __future__ import annotations

import re

from personal_assistant_dashboard.models import CalendarEvent

# Google puts this link in the description of every task-backed event.
_TASK_URL_RE = re.compile(r"https://tasks\.google\.com/task/([\w-]+)")


def is_task_event(event: CalendarEvent) -> bool:
    """True if this calendar event is really a Google Task with a due date."""
    return bool(_TASK_URL_RE.search(event.get("description", "")))
